const { useState } = React;
const root = ReactDOM.createRoot(document.querySelector('#root'));

const courses = ['자바스크립트 입문', '리액트 시작하기', 'CSS 레이아웃'];

const SearchBox = ({ keyword, onKeywordChange }) => (
  <div className="search">
    <label className="field" htmlFor="q">코스 검색</label>
    <input className="field__input" id="q" type="search" value={keyword}
      onChange={(event) => onKeywordChange(event.target.value)} />
  </div>
);

const Grid = ({ list }) => (
  <div className="grid">
    <p className="count">코스 {list.length}개</p>
    {list.map((course) => (
      <p className="course" key={course}>{course}</p>
    ))}
  </div>
);

const Panel = () => {
  const [keyword, setKeyword] = useState('');

  const found = courses.filter((course) => course.includes(keyword));

  return (
    <div className="panel">
      <SearchBox keyword={keyword} onKeywordChange={setKeyword} />
      <Grid list={found} />
    </div>
  );
};

root.render(<Panel />);

